// Types for the generated Carbon API operation manifest. The DATA is generated by
// `scripts/generate-mcp.ts` into the erp app's gitignored
// `routes/api+/mcp+/lib/tool-metadata.json` (its committed record is the sibling
// `tool-manifest.digest.json`); these types are the contract consumers read against.
// Keep them in sync with the generator's output shape.

export type Classification = "READ" | "WRITE" | "DESTRUCTIVE";

export type PermissionAction = "view" | "create" | "update" | "delete";

/**
 * The permission an API-key caller must hold to invoke the operation: the
 * module of the pages its gate names, and every action the gate's levels hold
 * (Edit lists view, create and update; the gate checks the highest).
 * `module` is `null` for operations that gate only on a valid key of the
 * company, or on pages of several modules.
 */
export interface ToolPermission {
  module: string | null;
  /** The page a gate of one page names (`inventory.receipts`); the key it checks is `<page>_<action>`. */
  page?: string;
  actions: PermissionAction[];
  /**
   * A gate that passes on any one of several pages (an `anyOf` or row rule):
   * the pages, in registry order, and their one level. `by` names the column
   * of the row that picks the page (`item.type`); empty, any page passes.
   */
  oneOf?: { pages: string[]; level: string; by: string[] };
}

/** One operation in the manifest — the successor of a `tool-metadata.json` entry. */
export interface ManifestEntry {
  name: string;
  module: string;
  classification: Classification;
  description: string;
  permission: ToolPermission;
  /** Whether the operation applies limit/offset itself. A list operation with
   *  `paginates: false` returns every row, and the MCP layer pages the response
   *  at its own boundary instead. */
  paginates: boolean;
  /** The JSON Schema for the operation's input. */
  schema: Record<string, unknown>;
  /** A service function's title: its TSDoc summary line. */
  title?: string;
  /** The operation's path in the ERP router (`["production", "cancelJob"]`).
   *  Its HTTP path is the path joined by `/`. */
  serviceFn: { path: string[] };
  /** The JSON Schema for the operation's RESPONSE `data`, reflected from the
   *  service function's TypeScript return type — absent when nothing useful could
   *  be derived (an `any`, a void, or an opaque shape). */
  responseSchema?: Record<string, unknown>;
}
